mkdir -p src && cat > src/claim-office.spec.ts <<'EOF'
import { describe, it } from "vitest";

/**
 * Adopted readings where the specification leaves a contract open:
 *
 * - "alike" components means exactly the same item type (2 runes + 1 moonstone
 *   gives no block), per the clarifying question in the specification.
 * - the special component block price applies only to a count of exactly 3 of
 *   one component type (4 runes -> 100 G, 7 runes -> 175 G).
 * - the first-insurance surcharge is a policy-wide modifier applied to every
 *   quote, per the "Long-standing customer's second contract" example.
 * - the follow-up discount applies to every quote after the customer's first
 *   quote within a scenario.
 * - rejections are observable as a thrown Error from the domain operation; the
 *   CLI translates that into a non-zero exit code plus a stderr description.
 *   The specification fixes neither an error class nor a message, so tests
 *   assert only that an Error is thrown / that the CLI exits non-zero.
 */

describe("MHPCO claim office", () => {
  // --- quote: base premiums per item type ---
  it.todo("quotes an empty item list as 5 G (processing fee only)");
  it.todo("quotes a plain sword as 105 G (100 G base + 5 G fee)");
  it.todo("quotes a plain amulet as 65 G (60 G base + 5 G fee)");
  it.todo("quotes a plain staff as 85 G (80 G base + 5 G fee)");
  it.todo("quotes a plain potion as 45 G (40 G base + 5 G fee)");
  it.todo("quotes a single rune as 30 G (25 G base + 5 G fee)");
  it.todo("quotes a single moonstone as 30 G (25 G base + 5 G fee)");
  it.todo("throws for a quote item with an unknown type such as broomstick");

  // --- quote: component building blocks ---
  it.todo("quotes 2 runes with a base premium of 50 G (no block)");
  it.todo("quotes 3 runes with a base premium of 60 G (block applies)");
  it.todo("quotes 4 runes with a base premium of 100 G (block requires exactly 3)");
  it.todo("quotes 7 runes with a base premium of 175 G (block requires exactly 3)");
  it.todo("quotes 2 runes + 1 moonstone with a base premium of 75 G (different types, no block)");
  it.todo("quotes 3 runes + 3 moonstones with a base premium of 120 G (two separate blocks)");
  it.todo("quotes 3 moonstones with a base premium of 60 G (block applies per component type)");

  // --- quote: item-specific modifiers ---
  it.todo("adds a 50 % curse surcharge to the affected item's base premium");
  it.todo("adds a 30 % surcharge for an item with enchantment exactly 5");
  it.todo("adds no high-enchantment surcharge for an item with enchantment 4");
  it.todo("adds both curse and high-enchantment surcharges to a cursed sword with enchantment 5");
  it.todo("applies the curse surcharge only to the cursed item on a multi-item policy -- cursed sword + plain amulet -> 215 G");

  // --- quote: policy-wide modifiers ---
  it.todo("applies the 20 % loyalty discount at exactly 2 years with MHPCO");
  it.todo("applies no loyalty discount at 1 year with MHPCO");
  it.todo("applies the 10 % first-insurance surcharge to the policy base premium");
  it.todo("applies the 15 % follow-up discount to every quote after the customer's first quote");
  it.todo("applies no follow-up discount to the customer's first quote");

  // --- quote: rounding ---
  it.todo("rounds a premium of 197.5 G up to 198 G (in the MHPCO's favour)");
  it.todo("keeps intermediate amounts as fractions and rounds only the final premium");

  // --- quote: integration examples ---
  it.todo("quotes a newcomer's cursed steel sword (enchantment 3) as 165 G");
  it.todo("quotes a 3-year customer's second contract for a cursed sword (enchantment 7) as 160 G");

  // --- claim: standard reimbursement ---
  it.todo("pays out 400 G for a steel sword (enchantment 3) with 500 G damage (full minus 100 G deductible)");
  it.todo("pays out 100 G for a rune with 200 G damage (no enchantment or material, so no special clause)");
  it.todo("reports the remaining cap after a claim (sword policy, cap 2000 G, payout 400 G -> 1600 G remaining)");

  // --- claim: special clauses ---
  it.todo("pays out 400 G for a steel sword with enchantment 9 and 1000 G damage (50 % clause, then deductible)");
  it.todo("pays out 400 G for a dragon-material sword with enchantment exactly 8 and 1000 G damage");
  it.todo("pays out 700 G for a dragon-material sword with enchantment 5 and 800 G damage (full reimbursement, then deductible)");
  it.todo("pays out 400 G for a dragon-material sword with enchantment 9 and 1000 G damage (50 % rule wins)");

  // --- claim: deductible per damage event ---
  it.todo("applies the 100 G deductible once per damaged item -- sword 500 G + amulet 300 G -> payout 600 G");

  // --- claim: rounding ---
  it.todo("rounds a payout of 350.5 G down to 350 G (in the MHPCO's favour)");

  // --- claim: insurance sum and cap ---
  it.todo("caps a policy at twice its insurance sum -- sword + amulet -> insurance sum 1600 G, cap 3200 G");
  it.todo("bases the cap on unmodified insurance values -- cursed sword -> cap 2000 G despite a 165 G premium");
  it.todo("bases the insurance sum on undiscounted component values -- sword + 3 runes -> insurance sum 1750 G, cap 3500 G");
  it.todo("carries the cap across successive claims -- 1500 G claim -> payout 1400 G, remaining cap 600 G");
  it.todo("reduces a later claim to the remaining cap -- second 1500 G claim -> payout 600 G, remaining cap 0 G");

  // --- claim: multiple items of the same type ---
  it.todo("insures two swords with an insurance sum of 2000 G and a cap of 4000 G");
  it.todo("treats two sword damage entries as separate damages, each with its own deductible");
  it.todo("throws when the damages contain more entries of a type than the policy covers");
  it.todo("throws when a damage entry refers to an item type not covered by the policy");
  it.todo("throws when a damage entry has an unknown item type");
  it.todo("throws when a damage entry has a negative amount such as -200");

  // --- CLI adapter ---
  it.todo("CLI reads a scenario from stdin and writes one result per step to stdout");
  it.todo("CLI writes quote results as { premium } and claim results as { payout, remainingCap }");
  it.todo("CLI resolves a claim's policy field to the quote step at that zero-based index");
  it.todo("CLI exits non-zero and writes to stderr for an unknown item type, writing no results to stdout");
  it.todo("CLI exits non-zero and writes to stderr for a claim damage not covered by the policy");
  it.todo("CLI exits non-zero and writes to stderr for a negative damage amount");
});
EOF
pnpm test 2>&1 | tail -12

