export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

const PROCESSING_FEE = 5;

/** The MHPCO price list for main items: one base premium per item type. */
const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

/** Components (runes, moonstones) are all priced at the same rate per component. */
const COMPONENT_TYPES = new Set(["rune"]);
const COMPONENT_BASE_PREMIUM = 25;

const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

/** The base premium the MHPCO charges for a single insured object. */
function basePremium(item: Item): number {
  if (COMPONENT_TYPES.has(item.type)) {
    return COMPONENT_BASE_PREMIUM;
  }
  return MAIN_ITEM_BASE_PREMIUMS[item.type];
}

/**
 * The policy base premium: the sum of the base premiums of all insured items,
 * before any policy-wide modifier or the processing fee.
 */
function policyBasePremium(items: Item[]): number {
  return items.reduce((total, item) => total + basePremium(item), 0);
}

/** Premiums are rounded up, in the MHPCO's favour. */
function roundPremiumInOfficesFavour(premium: number): number {
  return Math.ceil(premium);
}

export function quote(customer: Customer, items: Item[], previousQuoteCount: number): number {
  const basePremium = policyBasePremium(items);
  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
  return roundPremiumInOfficesFavour(
    basePremium + firstInsuranceSurcharge + PROCESSING_FEE,
  );
}
