import { policyBasePremium, type Item } from "./item-pricing.js";

export type { Item };

export interface Customer {
  yearsWithMHPCO: number;
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

/** Premiums are rounded up, in the MHPCO's favour. */
function roundPremiumInOfficesFavour(premium: number): number {
  return Math.ceil(premium);
}

/**
 * The initial assessment surcharge: a policy-wide modifier the MHPCO levies on
 * the policy base premium of every first insurance.
 */
function initialAssessmentSurcharge(policyBase: number): number {
  return policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
}

/**
 * The policy premium after the MHPCO's policy-wide modifiers: each modifier is
 * levied on the policy base premium, never on an already-modified amount.
 */
function premiumAfterPolicyWideModifiers(policyBase: number): number {
  return policyBase + initialAssessmentSurcharge(policyBase);
}

export function quote(customer: Customer, items: Item[], previousQuoteCount: number): number {
  const policyBase = policyBasePremium(items);
  return roundPremiumInOfficesFavour(
    premiumAfterPolicyWideModifiers(policyBase) + PROCESSING_FEE,
  );
}

