import { policyBasePremium, type Item } from "./item-pricing.js";
import { policyItemRiskSurcharges } from "./item-risk.js";

export type { Item };

export interface Customer {
  yearsWithMHPCO: number;
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

/** Premiums are rounded up, in the MHPCO's favour. */
function roundPremiumInOfficesFavour(premium: number): number {
  return Math.ceil(premium);
}

/**
 * The total of the MHPCO's policy-wide modifiers, each levied on the policy base
 * premium and never on an already-modified amount. Currently the rulebook holds
 * one such modifier: the initial assessment surcharge, which the office levies on
 * every first insurance.
 */
function policyWideModifiers(policyBase: number): number {
  return policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
}

/**
 * How the MHPCO assembles a premium: the policy base premium, plus the
 * item-specific risk surcharges (each levied on its own item's base premium),
 * plus the policy-wide modifiers (levied on the policy base premium), with the
 * processing fee added at the very end.
 */
export function quote(customer: Customer, items: Item[], previousQuoteCount: number): number {
  const policyBase = policyBasePremium(items);
  return roundPremiumInOfficesFavour(
    policyBase + policyItemRiskSurcharges(items) + policyWideModifiers(policyBase) + PROCESSING_FEE,
  );
}

