import { type Item } from "./item-pricing.js";

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

/** A policy the MHPCO has written: the items it covers and the cap still available. */
export interface Policy {
  items: Item[];
  remainingCap: number;
}

/** The cap a policy opens with. The office has not yet fixed this rule. */
const UNDECIDED_CAP = 0;

export function openPolicy(items: Item[]): Policy {
  return { items, remainingCap: UNDECIDED_CAP };
}

const DEDUCTIBLE_PER_DAMAGE_EVENT = 100;

/**
 * The share of a damage the MHPCO's rulebook reimburses. No special clause is
 * in force yet, so every damage is reimbursed in full.
 */
function reimbursedShareOf(damage: Damage): number {
  return damage.amount;
}

/**
 * What one damaged item earns its owner: the reimbursed share of the damage,
 * less the deductible the office withholds for each damage event.
 */
function settlementFor(damage: Damage): number {
  return reimbursedShareOf(damage) - DEDUCTIBLE_PER_DAMAGE_EVENT;
}

/**
 * How the MHPCO settles an incident: each damaged item is settled on its own,
 * and the payout is what the settlements add up to.
 */
export function claim(policy: Policy, incident: Incident): ClaimResult {
  const payout = incident.damages.reduce((running, damage) => running + settlementFor(damage), 0);
  return { payout, remainingCap: policy.remainingCap };
}
